/* Projected 3D geometry: each face is rotated, depth sorted and painted locally. */
class RobotScene{
 constructor(canvas,mode='overview'){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.mode=mode;this.yaw=-.56;this.pitch=.64;this.zoom=1;this.auto=!matchMedia('(prefers-reduced-motion: reduce)').matches;this.selected=0;this.time=0;this.last=0;this.visible=true;this.drag=false;this.pointer=null;this.faces=[];this.labels=[];this.point=null;this.disposed=false;this.image=new Image();this.image.src='assets/robot/robot-source.png';canvas.addEventListener('pointerdown',e=>{this.drag=true;this.auto=false;this.pointer=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing';canvas.dispatchEvent(new CustomEvent('scene-pause'));});canvas.addEventListener('pointermove',e=>{if(!this.drag)return;this.yaw+=(e.clientX-this.pointer[0])*.006;this.pitch=Math.max(.3,Math.min(.95,this.pitch+(e.clientY-this.pointer[1])*.003));this.pointer=[e.clientX,e.clientY]});canvas.addEventListener('pointerup',()=>{this.drag=false;canvas.style.cursor='grab'});this.observer=new IntersectionObserver(es=>this.visible=es[0].isIntersecting);this.observer.observe(canvas);this.tick=this.tick.bind(this);this.raf=requestAnimationFrame(this.tick);}
 project(p){let[x,y,z]=p;const c=Math.cos(this.yaw),s=Math.sin(this.yaw),a=x*c-z*s,b=x*s+z*c;const yy=y*Math.cos(this.pitch)+b*Math.sin(this.pitch),zz=b*Math.cos(this.pitch)-y*Math.sin(this.pitch);const k=this.scale/(1+zz/2200);return {x:this.w/2+a*k,y:this.h*.53-yy*k,z:zz,k};}
 face(pts,color,stroke){this.faces.push({pts,color,stroke,z:pts.reduce((a,p)=>a+this.project(p).z,0)/pts.length})}
 box(x,y,z,w,h,d,c='#284953'){const p=[[x,y,z],[x+w,y,z],[x+w,y,z+d],[x,y,z+d],[x,y+h,z],[x+w,y+h,z],[x+w,y+h,z+d],[x,y+h,z+d]];const shade=(col,n)=>{const v=col.match(/\w\w/g).map(x=>Math.min(255,Math.max(0,parseInt(x,16)+n)));return '#'+v.map(x=>x.toString(16).padStart(2,'0')).join('')};this.face([p[4],p[5],p[6],p[7]],shade(c.slice(1),18),'#97d5df13');this.face([p[0],p[1],p[5],p[4]],c,'#97d5df12');this.face([p[1],p[2],p[6],p[5]],shade(c.slice(1),-15),'#97d5df12');this.face([p[2],p[3],p[7],p[6]],shade(c.slice(1),-23));this.face([p[3],p[0],p[4],p[7]],shade(c.slice(1),-8));}
 line(a,b,c='#57d4cf',width=1){const x=this.project(a),y=this.project(b),ctx=this.ctx;ctx.beginPath();ctx.moveTo(x.x,x.y);ctx.lineTo(y.x,y.y);ctx.strokeStyle=c;ctx.lineWidth=width;ctx.stroke()}
 ring(x,y,z,r,c,width=1,start=0,end=Math.PI*2){const ctx=this.ctx;ctx.beginPath();for(let i=0;i<=120;i++){const a=start+(end-start)*i/120,p=this.project([x+Math.cos(a)*r,y,z+Math.sin(a)*r]);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)}ctx.strokeStyle=c;ctx.lineWidth=width;ctx.stroke()}
 robot(x,y,z,type,active=true){const col=active?'#b98b4c':'#3b4c55';if(type%2===0){this.box(x-20,y,z-14,40,18,28,col);this.box(x-13,y+18,z-11,26,14,22,'#afbfc2');this.box(x-8,y+32,z-7,16,7,14,'#d6dcda');this.box(x+12,y+20,z-12,7,4,5,'#54e0d1');for(const a of [-15,13]){this.box(x+a,y-3,z-17,6,10,5,'#111f2a');this.box(x+a,y-3,z+12,6,10,5,'#111f2a')}}else{this.box(x-22,y,z-13,44,25,26,col);this.box(x-9,y+25,z-9,18,11,18,'#cad6d6');this.box(x-4,y+36,z-3,8,20,6,'#586c75');this.box(x-13,y+52,z-9,26,11,18,'#bfcacb');this.box(x-9,y+55,z-10,9,6,2,'#47d5d0');}}
 geometry(){this.faces=[];const t=this.time;if(this.mode==='overview'){this.box(-170,-30,-130,340,20,260,'#152b38');this.box(-162,-10,-122,324,6,244,'#1d3d48');this.box(-49,-4,-44,98,28,88,'#25575d');this.box(-42,24,-37,84,18,74,'#316f76');this.box(-34,42,-30,68,11,60,'#4fa3a5');for(let i=0;i<3;i++){this.box(-29+i*21,53,-25,17,54,50,['#397c85','#60aeb2','#397c85'][i]);for(let n=0;n<3;n++)this.box(-27+i*21,64+n*13,-26,13,2,1,'#8beadf')}
 const loc=[[-220,-150],[205,-140],[-220,160],[210,155]];loc.forEach(([x,z],i)=>{this.box(x-44,-27,z-37,88,14,74,'#1a3542');this.box(x-39,-13,z-32,78,5,64,'#2b4f58');this.robot(x,-8,z,i,i!==2&&i!==3);this.labels.push({p:[x,68,z],text:['轨道巡检 / R-01','吊轨巡检 / R-02','工作面 / R-03','设备接入 / 16台'][i],status:i===2||i===3?'idle':'online',robotIndex:i});});
 }else{this.box(-340,-44,-100,680,18,200,'#1c3039');this.box(-330,-26,-90,660,5,180,'#253c43');for(let i=0;i<16;i++){const x=-318+i*41;this.box(x,70,-50,34,9,100,'#60777a');this.box(x,-22,-53,9,92,10,'#4b656b');this.box(x,-22,43,9,92,10,'#3c545c');this.box(x+4,40,42,9,8,26,'#9a7440');this.box(x+1,-9,-26,31,13,53,'#344c54');this.box(x+2,-8,43,29,14,10,'#334d55')}
 this.box(-333,47,-6,666,4,7,'#92a8ab');this.box(-333,-8,67,666,3,4,'#648b91');this.box(-333,-8,85,666,3,4,'#648b91');const x=-220+(Math.sin(t*.1)+1)*160;this.robot(x,14,0,1);this.box(-333,-8,-85,666,3,4,'#648b91');this.box(-333,-8,-67,666,3,4,'#648b91');this.robot(-160,-7,-76,0);this.robot(160,-7,-76,0,false);this.labels.push({p:[x,115,0],text:'R-02 吊轨机器人',status:'online',robotIndex:1},{p:[-160,47,-76],text:'R-01 轨道机器人',status:'online',robotIndex:0},{p:[160,47,-76],text:'R-03 通信离线',status:'idle',robotIndex:2});}}
 draw(){const canvas=this.canvas,rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const dpr=Math.min(devicePixelRatio||1,2);this.w=rect.width;this.h=rect.height;if(canvas.width!==Math.round(this.w*dpr)||canvas.height!==Math.round(this.h*dpr)){canvas.width=Math.round(this.w*dpr);canvas.height=Math.round(this.h*dpr)}const ctx=this.ctx;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,this.w,this.h);this.scale=Math.min(this.w/(this.mode==='overview'?640:820),this.h/460)*this.zoom;this.labels=[];
 const glow=ctx.createRadialGradient(this.w*.5,this.h*.58,0,this.w*.5,this.h*.58,this.w*.45);glow.addColorStop(0,'#30b6b519');glow.addColorStop(1,'#30b6b500');ctx.fillStyle=glow;ctx.fillRect(0,0,this.w,this.h);
 for(let n=-5;n<=5;n++){this.line([-450,-55,n*65],[450,-55,n*65],'#72a9b10a');this.line([n*80,-55,-330],[n*80,-55,330],'#72a9b10a')}this.ring(0,-40,0,this.mode==='overview'?290:355,'#5bafb52c',1);this.ring(0,-39,0,this.mode==='overview'?270:340,'#89e2e21b',1);this.ring(0,-37,0,this.mode==='overview'?292:357,'#6be8e3a0',2,this.time*.12,this.time*.12+.65);
 if(this.mode==='overview'){for(const[x,z]of[[-220,-150],[205,-140],[-220,160],[210,155]]){this.line([x,-5,z],[0,5,0],'#56bbb647',1);const f=(this.time*.18)%1;const p=this.project([x*(1-f),-3,z*(1-f)]);ctx.fillStyle='#8ee7dd';ctx.shadowBlur=12;ctx.shadowColor='#4ac5c5';ctx.beginPath();ctx.arc(p.x,p.y,2,0,7);ctx.fill();ctx.shadowBlur=0;}}
 this.geometry();this.faces.sort((a,b)=>b.z-a.z).forEach(f=>{ctx.beginPath();f.pts.forEach((p,i)=>{const a=this.project(p);i?ctx.lineTo(a.x,a.y):ctx.moveTo(a.x,a.y)});ctx.closePath();ctx.fillStyle=f.color;ctx.fill();if(f.stroke){ctx.strokeStyle=f.stroke;ctx.lineWidth=.6;ctx.stroke()}});
 this.labels.forEach((l,i)=>{const p=this.project(l.p),is=l.robotIndex===this.selected;ctx.font=`${is?'500':'400'} ${Math.max(10,this.w/75)}px Arial,Microsoft YaHei`;const tw=ctx.measureText(l.text).width;ctx.fillStyle=is?'#122e3be8':'#0c1e2acc';ctx.strokeStyle=is?'#69d9d377':'#48787a44';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(p.x-tw/2-13,p.y-18,tw+26,28,5);ctx.fill();ctx.stroke();ctx.fillStyle=l.status==='idle'?'#8a9ba3':'#a6d9d8';ctx.fillText(l.text,p.x-tw/2,p.y);});
 // A moving cross-section emphasizes a live spatial view without falsifying telemetry.
 if(this.mode==='monitor'){const x=-310+((this.time*18)%620);this.line([x,-20,-65],[x,92,-65],'#77e4dd66',1);this.line([x,92,-65],[x,92,60],'#77e4dd66',1);this.line([x,92,60],[x,-20,60],'#77e4dd66',1);}
 }
 tick(now){if(this.disposed)return;const dt=this.last?Math.min((now-this.last)/1000,.05):0;this.last=now;if(!document.hidden&&this.visible){if(!this.paused)this.time+=dt;if(this.auto)this.yaw+=dt*(this.mode==='overview'?.035:.012);this.draw()}this.raf=requestAnimationFrame(this.tick)}
 reset(){this.yaw=-.56;this.pitch=.64;this.zoom=1}dispose(){this.disposed=true;cancelAnimationFrame(this.raf);this.observer.disconnect()}
}window.RobotScene=RobotScene;



